#include <stdio.h>

int main(void) {
    int *value = NULL;
    if (value == NULL) {
        puts("No value is available");
    }
    return 0;
}

#include <stdio.h>

void print_value(const int *value) {
    if (value == NULL) {
        puts("No value");
        return;
    }
    printf("%d\n", *value);
}

int main(void) {
    int score = 91;
    print_value(&score);
    print_value(NULL);
    return 0;
}
